	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	// timeline functions:
	this.frame_0 = function() {
		this.gotoAndStop(0);
		
		
		this.addEventListener("mouseover", thisOver.bind(this));
		function thisOver() {
			this.gotoAndStop(1);
		}
		
		this.addEventListener("mouseout", thisOut.bind(this));
		function thisOut() {
			this.gotoAndStop(0);
		}
		
		this.addEventListener("mousedown", thisDown.bind(this));
		function thisDown() {
			this.gotoAndStop(2);
		}
		
		window.addEventListener("mouseup", thisUp.bind(this));
		function thisUp() {
			if (mousePosX >= this.x + this.parent.x - 300 && mousePosX <= this.x + this.parent.x) {
				if (mousePosY >= this.y + this.parent.y - 70 && mousePosY <= this.y + this.parent.y) {
					this.gotoAndStop(1);
				}
			}
		}
		
		var mousePosX;
		var mousePosY;
		
		this.addEventListener("tick", main_fs.bind(this));
		function main_fs() {
		
			mousePosX = stage.mouseX / canvas.width * 1280;
			mousePosY = stage.mouseY / canvas.height * 720;
			
		}
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(3));

