		function getRarity(chances) {
			var rand = Math.random();
			if (rand <= chances[0]) {
				return 1;
			}
			else if (rand <= chances[0]+chances[1]) {
				return 2;
			}
			else if (rand <= chances[0]+chances[1]+chances[2]) {
				return 3;
			}
			else if (rand <= chances[0]+chances[1]+chances[2]+chances[3]) {
				return 4;
			}
			else if (rand <= chances[0]+chances[1]+chances[2]+chances[3]+chances[4]) {
				return 5;
			}
			else if (rand <= chances[0]+chances[1]+chances[2]+chances[3]+chances[4]+chances[5]) {
				return 6;
			}
		}
		
		
		
		
		function setDM(e) {
			var dmgPop = e.currentTarget;
			dmgPop.dmg.text = dmgPop.txt;
			dmgPop.y -= 3;
			dmgPop.alpha -= 1/20;
			
			if (dmgPop.alpha <= 0) {
				dmgPop.alpha = 0;
				dmgPop.visible = false;
				dmgPop.removeEventListener('tick', setDM);
				stage.removeChild(dmgPop);
			}
			
		}
		
