		function setEq(num) {
			if (inventory.cells[num].is) {
				if (isEquip == 1 && player.level >= inventory.cells[num].eq.level) {
					if (inventory.cells[num].eq.type == 1) {
						if (equipment.helmet.is) {
							var store = equipment.helmet;
							equipment.helmet = inventory.cells[num].eq;
							inventory.cells[num].eq = store;
						}
						else {
							equipment.helmet = inventory.cells[num].eq;
							inventory.cells[num].is = false;
						}
					}
					else if (inventory.cells[num].eq.type == 2) {
						if (equipment.armor.is) {
							var store = equipment.armor;
							equipment.armor = inventory.cells[num].eq;
							inventory.cells[num].eq = store;
						}
						else {
							equipment.armor = inventory.cells[num].eq;
							inventory.cells[num].is = false;
						}
					}
					else if (inventory.cells[num].eq.type == 3) {
						if (equipment.boots.is) {
							var store = equipment.boots;
							equipment.boots = inventory.cells[num].eq;
							inventory.cells[num].eq = store;
						}
						else {
							equipment.boots = inventory.cells[num].eq;
							inventory.cells[num].is = false;
						}
					}
					else if (inventory.cells[num].eq.type == 4) {
						if (equipment.sword.is) {
							var store = equipment.sword;
							equipment.sword = inventory.cells[num].eq;
							inventory.cells[num].eq = store;
						}
						else {
							equipment.sword = inventory.cells[num].eq;
							inventory.cells[num].is = false;
						}
					}
					else if (inventory.cells[num].eq.type == 5) {
						if (equipment.shield.is) {
							var store = equipment.shield;
							equipment.shield = inventory.cells[num].eq;
							inventory.cells[num].eq = store;
						}
						else {
							equipment.shield = inventory.cells[num].eq;
							inventory.cells[num].is = false;
						}
					}
					else if (inventory.cells[num].eq.type == 6) {
						if (equipment.ring.is) {
							var store = equipment.ring;
							equipment.ring = inventory.cells[num].eq;
							inventory.cells[num].eq = store;
						}
						else {
							equipment.ring = inventory.cells[num].eq;
							inventory.cells[num].is = false;
						}
					}
					else if (inventory.cells[num].eq.type == 7) {
						if (equipment.amulet.is) {
							var store = equipment.amulet;
							equipment.amulet = inventory.cells[num].eq;
							inventory.cells[num].eq = store;
						}
						else {
							equipment.amulet = inventory.cells[num].eq;
							inventory.cells[num].is = false;
						}
					}
				}
				else if (isEquip == 0) {
					money = money.plus(inventory.cells[num].eq.price)
					inventory.cells[num].is = false;
				}
			}
		}
		
		
