		function randomNameGen() {
			var names = ["Goblin", "Orc", "Ogre", "Wolf", "Bear",
						"Spider", "Bat", "Fox", "Troll", "Skeleton",
						"Fly", "Demon", "Dragon", "Bandit", "Zombie",
						"Pig", "Devil", "Harpy", "Mermaid", "Werewolf"];
			var rand = Math.floor(Math.random()*20);
			return names[rand];
		}
		
		
		
		
		
		this.clickDamage.addEventListener("mousedown", dealDamage.bind(this));
		function dealDamage() {
			if (player.hp.gt(0)) {
				if (nd(Math.random()).gte(enemy.evade)) {
					enemy.hp = enemy.hp.sub(player.dps.div(10));
						var dmgPop;
						dmgPop = new lib.dmgPopup();
						dmgPop.x = 825;
						dmgPop.y = 275;
							
						dmgPop.txt = "-" + format(player.dps.div(10));
						dmgPop.dmg.text = dmgPop.txt;
						
						dmgPop.scaleX = 1.25;
						dmgPop.scaleY = 1.25;
							
						stage.addChild(dmgPop);
						dmgPop.addEventListener('tick', setDM);
					}
					else {
						var dmgPop;
						dmgPop = new lib.dmgPopup();
						dmgPop.x = 825;
						dmgPop.y = 275;
								
						dmgPop.txt = "evaded";
						dmgPop.dmg.text = dmgPop.txt;
							
						dmgPop.scaleX = 1;
						dmgPop.scaleY = 1;
							
						stage.addChild(dmgPop);
						dmgPop.addEventListener('tick', setDM);
				}
			}
		}
		
		
		
