		function thePrestige() {
			prestigeNow = prestigeNext;
			equipment = new equipmentC();
			inventory = new inventoryC();
			player = new playerC(1);
			enemy = new enemyC(1);
			
			curStage = 1;
			maxStage = 1;
			progress = 0;
			maxP = 5;
			firstFreeCell = 0;
			money = nd(0);
			
			upgrades = [new upgradeC(30, nd(10), nd(3)), new upgradeC(1, nd(200), nd(1)),
						new upgradeC(1, nd(1000), nd(1)), new upgradeC(1, nd(5000), nd(1)),
						new upgradeC(1, nd(20000), nd(1)), new upgradeC(50, nd(100000), nd(1.5)),
						new upgradeC(10, nd(1000000), nd(2)), new upgradeC(10, nd(1000000000), nd(2))];
		
		
			customLvl = 1;
			autoRestart = false;
			autoSell = false;
			prestigeClicks = 5;
		}
		
		
