		this.uWindow.uUpgrade.addEventListener("mousedown", upgradeGearF.bind(this));
		function upgradeGearF() {
			if (upgradeGear == 0) {
				var uCost = equipment.helmet.price.times(3);
				if (money.gte(uCost) && player.level > equipment.helmet.level) {
					money = money.sub(uCost);
					var varWas = equipment.helmet.variation;
					equipment.helmet = new gear(true, equipment.helmet.level+1, equipment.helmet.rarity, 1);
					equipment.helmet.variation = varWas;
				}
			}
			if (upgradeGear == 1) {
				var uCost = equipment.armor.price.times(3);
				if (money.gte(uCost) && player.level > equipment.armor.level) {
					money = money.sub(uCost);
					var varWas = equipment.armor.variation;
					equipment.armor = new gear(true, equipment.armor.level+1, equipment.armor.rarity, 2);
					equipment.armor.variation = varWas;
				}
			}
			if (upgradeGear == 2) {
				var uCost = equipment.boots.price.times(2);
				if (money.gte(uCost) && player.level > equipment.boots.level) {
					money = money.sub(uCost);
					var varWas = equipment.boots.variation;
					equipment.boots = new gear(true, equipment.boots.level+1, equipment.boots.rarity, 3);
					equipment.boots.variation = varWas;
				}
			}
			if (upgradeGear == 3) {
				var uCost = equipment.sword.price.times(5);
				if (money.gte(uCost) && player.level > equipment.sword.level) {
					money = money.sub(uCost);
					var varWas = equipment.sword.variation;
					var speedWas = equipment.sword.speed;
					equipment.sword = new gear(true, equipment.sword.level+1, equipment.sword.rarity, 4);
					equipment.sword.variation = varWas;
					equipment.sword.speed = speedWas;
					equipment.sword.damage = equipment.sword.mainStat.times(equipment.sword.speed);
				}
			}
			if (upgradeGear == 4) {
				var uCost = equipment.shield.price.times(3);
				if (money.gte(uCost) && player.level > equipment.shield.level) {
					money = money.sub(uCost);
					var varWas = equipment.shield.variation;
					equipment.shield = new gear(true, equipment.shield.level+1, equipment.shield.rarity, 5);
					equipment.shield.variation = varWas;
				}
			}
			if (upgradeGear == 5) {
				var uCost = equipment.ring.price.times(2);
				if (money.gte(uCost) && player.level > equipment.ring.level) {
					money = money.sub(uCost);
					var varWas = equipment.ring.variation;
					equipment.ring = new gear(true, equipment.ring.level+1, equipment.ring.rarity, 6);
					equipment.ring.variation = varWas;
				}
			}
			if (upgradeGear == 6) {
				var uCost = equipment.amulet.price.times(2);
				if (money.gte(uCost) && player.level > equipment.amulet.level) {
					money = money.sub(uCost);
					var varWas = equipment.amulet.variation;
					equipment.amulet = new gear(true, equipment.amulet.level+1, equipment.amulet.rarity, 7);
					equipment.amulet.variation = varWas;
				}
			}
		}
		
		
		
